-- =====================================================================
-- MatchIn v2 — Seed Data
-- Data uji untuk mahasiswa Teknik Informatika, Ilmu Komputer & Teknik
-- Komputer. 3 angkatan aktif (semester 2, 4, 6) x 6 mata kuliah x 2 kelas
-- (A/B) x 30 mahasiswa/kelas = 180 mahasiswa, masing-masing 3 skill +
-- preferensi partner per kelas yang diikuti + 1 foto profil default.
--
-- Password semua akun (termasuk 6 akun demo mahasiswa1..6@demo.ac.id): password
-- =====================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";
SET NAMES utf8mb4;

-- Avatar placeholder default untuk seluruh mahasiswa (PNG, ~15KB, disimpan
-- sekali sebagai session variable supaya tidak diulang di 180 baris INSERT).
SET @default_photo = ;
SET @default_photo_mime = 'image/png';

